import json
from datetime import datetime, timedelta

FILE = "/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-15-projects-vla-ssd--claude-sessions-agent-3425744c/5509cac4-948e-4448-8e19-69fa48f8e602/tool-results/mcp-agent-ml-research-read_registry-1778902302007.txt"

with open(FILE, 'r') as f:
    raw = json.load(f)

# The outer wrapper has a "result" key whose value is a JSON string
registry_str = raw.get("result", raw)
if isinstance(registry_str, str):
    registry = json.loads(registry_str)
else:
    registry = registry_str

# registry could be a dict with "experiments" key, or a list
if isinstance(registry, dict):
    experiments = registry.get("experiments", registry)
    if isinstance(experiments, dict):
        # Convert dict of exp_id -> exp_data to list
        exp_list = []
        for eid, edata in experiments.items():
            if isinstance(edata, dict):
                edata["_id"] = eid
                exp_list.append(edata)
            else:
                exp_list.append({"_id": eid, "raw": edata})
        experiments = exp_list
elif isinstance(registry, list):
    experiments = registry
else:
    print(f"Unexpected registry type: {type(registry)}")
    print(str(registry)[:500])
    exit()

# Normalize: get exp_id
for e in experiments:
    if "_id" not in e:
        e["_id"] = e.get("exp_id", e.get("id", "unknown"))

# Count by status
status_counts = {}
for e in experiments:
    s = e.get("status", "unknown")
    status_counts[s] = status_counts.get(s, 0) + 1

print("=" * 60)
print("STATUS COUNTS")
print("=" * 60)
for s, c in sorted(status_counts.items(), key=lambda x: -x[1]):
    print(f"  {s}: {c}")
print(f"  TOTAL: {len(experiments)}")

# RUNNING or PREPARING
print("\n" + "=" * 60)
print("RUNNING / PREPARING")
print("=" * 60)
for e in experiments:
    if e.get("status") in ("RUNNING", "PREPARING"):
        eid = e["_id"]
        status = e.get("status")
        hyp = e.get("hypothesis", "N/A")
        server = e.get("server", e.get("spec", {}).get("server", "N/A") if isinstance(e.get("spec"), dict) else "N/A")
        gpu = e.get("gpu", e.get("gpu_ids", e.get("spec", {}).get("gpu", "N/A") if isinstance(e.get("spec"), dict) else "N/A"))
        print(f"  [{status}] {eid}")
        print(f"    hypothesis: {hyp}")
        print(f"    server: {server}, GPU: {gpu}")

# PENDING or QUEUED
print("\n" + "=" * 60)
print("PENDING / QUEUED")
print("=" * 60)
found_pq = False
for e in experiments:
    if e.get("status") in ("PENDING", "QUEUED"):
        found_pq = True
        eid = e["_id"]
        status = e.get("status")
        hyp = e.get("hypothesis", "N/A")
        print(f"  [{status}] {eid}: {hyp}")
if not found_pq:
    print("  (none)")

# DONE in last 24h
print("\n" + "=" * 60)
print("DONE (last 24h)")
print("=" * 60)
now = datetime.utcnow()
cutoff = now - timedelta(hours=24)
found_done = False
for e in experiments:
    if e.get("status") == "DONE":
        # Try to find completion time
        completed = e.get("completed_at", e.get("updated_at", e.get("finished_at", "")))
        if not completed:
            # Check spec
            spec = e.get("spec", {})
            if isinstance(spec, dict):
                completed = spec.get("completed_at", "")

        is_recent = False
        if completed:
            try:
                # Try parsing various formats
                for fmt in ["%Y-%m-%dT%H:%M:%S.%fZ", "%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"]:
                    try:
                        dt = datetime.strptime(completed, fmt)
                        if dt > cutoff:
                            is_recent = True
                        break
                    except ValueError:
                        continue
            except:
                pass

        if is_recent:
            found_done = True
            eid = e["_id"]
            conclusion = e.get("conclusion", "N/A")
            metrics = e.get("metrics", e.get("result_metrics", {}))
            if not metrics:
                metrics = {}
            metrics_str = ", ".join(f"{k}={v}" for k, v in metrics.items()) if isinstance(metrics, dict) else str(metrics)
            print(f"  {eid} | conclusion={conclusion} | completed={completed}")
            print(f"    metrics: {metrics_str if metrics_str else 'N/A'}")

if not found_done:
    # Show all DONE with their dates so user can see
    print("  No DONE experiments found in last 24h. Showing all DONE with timestamps:")
    for e in experiments:
        if e.get("status") == "DONE":
            eid = e["_id"]
            conclusion = e.get("conclusion", "N/A")
            completed = e.get("completed_at", e.get("updated_at", e.get("finished_at", "no-timestamp")))
            metrics = e.get("metrics", e.get("result_metrics", {}))
            if not metrics:
                metrics = {}
            metrics_str = ", ".join(f"{k}={v}" for k, v in metrics.items()) if isinstance(metrics, dict) else str(metrics)
            print(f"  {eid} | conclusion={conclusion} | completed={completed}")
            if metrics_str:
                print(f"    metrics: {metrics_str}")

